using Npgsql; var builder = WebApplication.CreateBuilder(args); var app = builder.Build(); var cs = Environment.GetEnvironmentVariable("DB_CONNECTION") ?? "Host=db;Port=5432;Database=library_db;Username=postgres;Password=password123"; await using (var c = new NpgsqlConnection(cs)) { await c.OpenAsync(); await new NpgsqlCommand("CREATE TABLE IF NOT EXISTS books(id SERIAL PRIMARY KEY,title TEXT NOT NULL,author TEXT NOT NULL,is_available BOOLEAN NOT NULL DEFAULT TRUE);", c).ExecuteNonQueryAsync(); } app.MapGet("/books", async () => { var l = new List<object>(); await using var c = new NpgsqlConnection(cs); await c.OpenAsync(); await using var r = await new NpgsqlCommand("SELECT id,title,author,is_available FROM books ORDER BY id", c).ExecuteReaderAsync(); while (await r.ReadAsync()) l.Add(new { Id = r.GetInt32(0), Title = r.GetString(1), Author = r.GetString(2), IsAvailable = r.GetBoolean(3) }); return Results.Ok(l); }); app.MapPost("/books", async (BookDto d) => { await using var c = new NpgsqlConnection(cs); await c.OpenAsync(); var cmd = new NpgsqlCommand("INSERT INTO books(title,author,is_available)VALUES(@t,@a,TRUE)RETURNING id", c); cmd.Parameters.AddWithValue("t", d.Title); cmd.Parameters.AddWithValue("a", d.Author); var id = (int)(await cmd.ExecuteScalarAsync())!; return Results.Created($"/books/{id}", new { Id = id, d.Title, d.Author, IsAvailable = true }); }); app.MapPost("/books/{id:int}/reserve", async (int id) => { await using var c = new NpgsqlConnection(cs); await c.OpenAsync(); var cmd = new NpgsqlCommand("UPDATE books SET is_available=FALSE WHERE id=@id AND is_available=TRUE", c); cmd.Parameters.AddWithValue("id", id); return await cmd.ExecuteNonQueryAsync() > 0 ? Results.Ok(new { Message = "Reserved" }) : Results.BadRequest(new { Error = "Unavailable" }); }); app.Run(); record BookDto(string Title, string Author);
